import math
import sys

if hasattr(sys, 'set_int_max_str_digits'):
    try:
        sys.set_int_max_str_digits(0)
    except Exception:
        pass


def _trunc_div(a: int, b: int) -> int:
    if b == 0:
        raise ValueError("Division by zero")
    sign = -1 if (a < 0) ^ (b < 0) else 1
    return sign * (abs(a) // abs(b))


def _trunc_mod(a: int, b: int) -> int:
    if b == 0:
        raise ValueError("Modulo by zero")
    q = _trunc_div(a, b)
    return a - b * q


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    # 1. Lexing
    i = 0
    n = len(expr)
    raw_tokens = []
    while i < n:
        c = expr[i]
        if c in ' \t\n\r':
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            raw_tokens.append(('NUM', int(expr[start:i])))
            continue
        if c == '+':
            raw_tokens.append(('PLUS', '+'))
        elif c == '-':
            raw_tokens.append(('MINUS', '-'))
        elif c == '*':
            raw_tokens.append(('STAR', '*'))
        elif c == '/':
            raw_tokens.append(('SLASH', '/'))
        elif c == '%':
            raw_tokens.append(('PERCENT', '%'))
        elif c == '^':
            raw_tokens.append(('CARET', '^'))
        elif c == '!':
            raw_tokens.append(('BANG', '!'))
        elif c == '(':
            raw_tokens.append(('LPAREN', '('))
        elif c == ')':
            raw_tokens.append(('RPAREN', ')'))
        else:
            raise ValueError(f"Invalid character: {c!r}")
        i += 1

    if not raw_tokens:
        raise ValueError("Empty expression")

    # 2. Token validation, distinguishing unary minus, and inserting implicit multiplication
    tokens = []
    want_operand = True
    paren_depth = 0

    for tok_type, tok_val in raw_tokens:
        if want_operand:
            if tok_type == 'NUM':
                tokens.append(('NUM', tok_val))
                want_operand = False
            elif tok_type == 'LPAREN':
                tokens.append(('LPAREN', '('))
                paren_depth += 1
                want_operand = True
            elif tok_type == 'MINUS':
                tokens.append(('UNARY_MINUS', '-'))
                want_operand = True
            else:
                raise ValueError(f"Unexpected token {tok_val!r} when expecting operand")
        else:
            if tok_type in ('PLUS', 'STAR', 'SLASH', 'PERCENT', 'CARET'):
                tokens.append((tok_type, tok_val))
                want_operand = True
            elif tok_type == 'MINUS':
                tokens.append(('MINUS', '-'))
                want_operand = True
            elif tok_type == 'BANG':
                tokens.append(('BANG', '!'))
                want_operand = False
            elif tok_type == 'RPAREN':
                if paren_depth == 0:
                    raise ValueError("Unmatched closing parenthesis")
                paren_depth -= 1
                tokens.append(('RPAREN', ')'))
                want_operand = False
            elif tok_type == 'LPAREN':
                # Implicit multiplication
                tokens.append(('STAR', '*'))
                tokens.append(('LPAREN', '('))
                paren_depth += 1
                want_operand = True
            else:
                raise ValueError(f"Unexpected token {tok_val!r} after operand")

    if want_operand:
        raise ValueError("Incomplete expression")
    if paren_depth != 0:
        raise ValueError("Unclosed parenthesis")

    # 3. Parsing and evaluation via Pratt parsing
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return ('EOF', None)

    def get():
        nonlocal pos
        tok = peek()
        pos += 1
        return tok

    def parse_expr(min_prec: int) -> int:
        tok_type, tok_val = get()

        # Prefix denotation
        if tok_type == 'NUM':
            left = tok_val
        elif tok_type == 'UNARY_MINUS':
            left = -parse_expr(30)
        elif tok_type == 'LPAREN':
            left = parse_expr(0)
            close_tok = get()
            if close_tok[0] != 'RPAREN':
                raise ValueError("Expected closing parenthesis")
        else:
            raise ValueError(f"Unexpected token {tok_type}")

        # Infix and Postfix denotation
        while True:
            next_type = peek()[0]

            if next_type == 'BANG':
                lbp = 50
            elif next_type == 'CARET':
                lbp = 40
            elif next_type in ('STAR', 'SLASH', 'PERCENT'):
                lbp = 20
            elif next_type in ('PLUS', 'MINUS'):
                lbp = 10
            else:
                lbp = 0

            if lbp <= min_prec:
                break

            op_type = get()[0]

            if op_type == 'BANG':
                if left < 0:
                    raise ValueError("Factorial of negative number")
                try:
                    left = math.factorial(left)
                except OverflowError:
                    raise ValueError("Factorial result too large")
            elif op_type == 'CARET':
                right = parse_expr(39)  # Right-associative
                if right < 0:
                    raise ValueError("Negative exponent")
                left = left ** right
            elif op_type == 'STAR':
                right = parse_expr(21)
                left = left * right
            elif op_type == 'SLASH':
                right = parse_expr(21)
                left = _trunc_div(left, right)
            elif op_type == 'PERCENT':
                right = parse_expr(21)
                left = _trunc_mod(left, right)
            elif op_type == 'PLUS':
                right = parse_expr(11)
                left = left + right
            elif op_type == 'MINUS':
                right = parse_expr(11)
                left = left - right
            else:
                raise ValueError(f"Unexpected operator {op_type}")

        return left

    result = parse_expr(0)
    if pos != len(tokens):
        raise ValueError("Unparsed tokens remaining")
    return result
